(function(){var cfg=window.wxszbpc_config||{};if(cfg.enableAiSearch){function wxszbpc_addAiSearchButton(form){if(!form||document.getElementById('search-heoGPT-tips'))return;var aiSearchLink=document.createElement('a');aiSearchLink.id='search-heoGPT-tips';aiSearchLink.className='search-ai-btn';aiSearchLink.href='javascript:;';aiSearchLink.rel='external nofollow';aiSearchLink.title='数字人助理';aiSearchLink.innerHTML='<i class="fa fa-smile-o"></i>'+'<span class="search-heoGPT-text">试试使用AI进行搜索，搜索结果更加精准</span>'+'<span class="search-heoGPT-text-right">推荐</span>';form.parentNode.insertBefore(aiSearchLink,form.nextSibling);aiSearchLink.addEventListener('click',function(event){event.preventDefault();var searchInput=form.querySelector('input[name="s"]');if(!searchInput){if(typeof notyf!=='undefined')notyf('搜索输入框加载失败，请刷新页面重试～','warning');return;}var searchContent=searchInput.value.trim();if(!searchContent){if(typeof notyf!=='undefined')notyf('请输入搜索内容后再使用AI搜索～','warning');searchInput.focus();return;}if(typeof postChatUser==='undefined'||typeof postChatUser.sendSearchMsg!=='function'){if(typeof notyf!=='undefined')notyf('AI搜索功能暂不可用，请稍后再试～','warning');return;}try{postChatUser.sendSearchMsg(searchContent);}catch(e){if(typeof notyf!=='undefined')notyf('AI搜索请求失败，请稍后再试～','warning');}});}function wxszbpc_initAISearch(){var modalSearchContainer=document.querySelector('.main-search.fixed-body.main-bg.box-body.navbar-search.nopw-sm');if(modalSearchContainer){var modalObserver=new MutationObserver(function(mutationsList){mutationsList.forEach(function(mutation){if(mutation.type==='attributes'&&mutation.attributeName==='class'&&modalSearchContainer.classList.contains('show')){var modalForm=modalSearchContainer.querySelector('form.padding-10.search-form[method="get"]');if(modalForm){wxszbpc_addAiSearchButton(modalForm);modalObserver.disconnect();}}});});modalObserver.observe(modalSearchContainer,{attributes:true});}else{document.querySelectorAll('form.padding-10.search-form[method="get"]').forEach(function(form){wxszbpc_addAiSearchButton(form);});}if(cfg.isHomePage&&!cfg.isMobile){var targetDiv=document.querySelector('.abs-right.muted-color');if(targetDiv){var buttonToRemove=targetDiv.querySelector('button');if(buttonToRemove)targetDiv.removeChild(buttonToRemove);var newLink=document.createElement('a');newLink.id='aisearch';newLink.className='btn wxs-search-button-red';newLink.innerHTML='AI搜索';var newButton=document.createElement('button');newButton.type='submit';newButton.tabIndex=2;newButton.className='btn wxs-search-button-blue';newButton.textContent='站内搜索';targetDiv.appendChild(newLink);targetDiv.appendChild(newButton);newLink.addEventListener('click',function(event){event.preventDefault();var searchInput=document.getElementsByName('s')[0];if(searchInput&&typeof postChatUser!=='undefined'&&postChatUser.sendSearchMsg){postChatUser.sendSearchMsg(searchInput.value);}});}}}}if(cfg.aiBtnSelector){function wxszbpc_initAIButton(){var el=document.querySelector('a[href="'+cfg.aiBtnSelector+'"]');if(!el)return;el.setAttribute('href','javascript:;');el.classList.add('aitip');el.addEventListener('click',function(){var questionTitle;if(cfg.defaultInput){questionTitle=cfg.defaultInput;}else{var title=document.title;if(cfg.excludeSiteTitle&&cfg.siteName){title=title.replace(new RegExp('\\s*[-|–|—]\\s*'+cfg.siteName.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*$','g'),'');title=title.replace(new RegExp('\\s*\\|\\s*'+cfg.siteName.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\s*$','g'),'');title=title.trim();}questionTitle='请问在《'+title+'》中';}if(typeof postChatUser!=='undefined'&&postChatUser.setPostChatInput){postChatUser.setPostChatInput(questionTitle);var themeCookie=document.cookie.split('; ').find(function(row){return row.startsWith('theme_mode=');});if(themeCookie){var mode=themeCookie.split('=')[1];if(mode==='white-theme'){postChatUser.setPostChatTheme('light');}else if(mode==='dark-theme'){postChatUser.setPostChatTheme('dark');}}else{var isDark=document.body.classList.contains('dark-theme');postChatUser.setPostChatTheme(isDark?'dark':'light');}}});if(cfg.aiBtnSvgIcon){var svgUse=el.querySelector('svg use');if(svgUse)svgUse.setAttribute('xlink:href',cfg.aiBtnSvgIcon);}}}function wxszbpc_init(){if(cfg.enableAiSearch&&typeof wxszbpc_initAISearch==='function'){wxszbpc_initAISearch();}if(cfg.aiBtnSelector&&typeof wxszbpc_initAIButton==='function'){wxszbpc_initAIButton();}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',wxszbpc_init);}else{wxszbpc_init();}})();